-- CREATE 2026 Internal Hub seed. Idempotent: skips if already seeded.
do $$ declare pid uuid; did uuid; begin
  select id into pid from projects where name = 'CREATE 2026';
  if pid is null then raise notice 'CREATE 2026 not found'; return; end if;
  if exists (select 1 from onsite_team where project_id = pid) then raise notice 'Internal hub already seeded'; return; end if;
end $$;
